from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    comp = [[-1] * w for _ in range(h)]
    markers = {}

    # Label the 4-connected non-background objects and record their markers.
    cid = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            markers[cid] = []
            while q:
                y, x = q.popleft()
                comp[y][x] = cid
                if grid[y][x] not in (0, 1):
                    markers[cid].append((y, x, grid[y][x]))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            cid += 1

    # Color cells whose complete 3x3 neighborhood belongs to the same
    # non-background object as a colored marker.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            k = comp[r][c]
            if k < 0 or not markers[k]:
                continue
            if all(comp[y][x] == k
                   for y in range(r - 1, r + 2)
                   for x in range(c - 1, c + 2)):
                seeds = markers[k]
                if len(seeds) == 1:
                    out[r][c] = seeds[0][2]
                else:
                    _, _, color = min(seeds, key=lambda s: (r-s[0])**2 + (c-s[1])**2)
                    out[r][c] = color

    return out
